package owl.nh;
import java.util.*;
import net.runelite.api.*;
public final class OlmHeadCombatTests {
 static void check(boolean ok,String message){CoreTests.check(ok,"Olm head DPS: "+message);}
 static OlmSpecials.Cell c(int x,int y){return new OlmSpecials.Cell(x,y,0);}
 public static void main(String[] args)throws Exception{
  check(OlmMechanicAdapter.awaitingStep(c(0,0),c(1,0),10,10)&&OlmMechanicAdapter.awaitingStep(c(0,0),c(1,0),11,10),"one move request survives client cycles and the next movement tick");
  check(!OlmMechanicAdapter.awaitingStep(c(1,0),c(1,0),10,10),"observed arrival immediately releases movement for an attack");
  check(!OlmMechanicAdapter.awaitingStep(c(0,0),c(1,0),12,10),"ignored movement becomes retryable after two game ticks");
  OlmSpecials.View pendingView=new OlmSpecials.View();pendingView.player=c(0,0);check(OlmMechanicAdapter.pendingDodgeSafe(pendingView,c(1,0)),"clear pending destination is retained");pendingView.hazards.add(new OlmSpecials.Hazard(c(1,0),OlmSpecials.HazardKind.FALLING,0));check(!OlmMechanicAdapter.pendingDodgeSafe(pendingView,c(1,0)),"new danger at the requested destination bypasses suppression immediately");
  check(OlmHeadCombat.mayShoot(true,true,false,8,10,true),"an in-range pool hold can use the normal attack slot");check(!OlmHeadCombat.mayShoot(true,true,true,8,10,true)&&!OlmHeadCombat.mayShoot(true,true,false,11,10,true)&&!OlmHeadCombat.mayShoot(true,true,false,8,10,false),"pending movement, missing range and blocked sight prevent an unsafe chase");
  OlmSpecials.View view=new OlmSpecials.View();view.player=c(0,0);view.tick=100;OlmPoolDuty duty=new OlmPoolDuty();Set<OlmSpecials.Cell> pools=new HashSet<>(Arrays.asList(c(1,0),c(4,0)));duty.observe(100,view.player,pools);view.hazards.add(new OlmSpecials.Hazard(c(1,0),OlmSpecials.HazardKind.FALLING,0));Map<OlmSpecials.Cell,Integer> routes=new LinkedHashMap<>();routes.put(c(1,0),1);routes.put(c(4,0),4);check(OlmHeadCombat.choosePool(routes,view,duty,true).equals(c(4,0)),"choose the crystal-free pool reachable within the eight-of-ten budget");routes.put(c(4,0),6);check(OlmHeadCombat.choosePool(routes,view,duty,true).equals(c(1,0)),"do not sacrifice the pool deadline for a distant clear pool");
  duty.reset();for(int tick=200;tick<=207;tick++)duty.observe(tick,c(1,0),pools);view.player=c(1,0);view.tick=208;routes.put(c(1,0),0);routes.put(c(4,0),4);check(OlmHeadCombat.choosePool(routes,view,duty,true).equals(c(1,0)),"eight credited ticks do not justify arriving at the other pool after the final resolution");view.hazards.clear();routes.put(c(4,0),1);check(OlmHeadCombat.choosePool(routes,view,duty,true).equals(c(1,0)),"a clear occupied pool stays stationary");
  Map<String,Object> clientFields=new HashMap<>();clientFields.put("getGameCycle",100);Client client=ChambersTests.fake(Client.class,clientFields);OlmMechanicAdapter adapter=new OlmMechanicAdapter(client);adapter.configure(new OlmFighter.Profile());adapter.start();java.lang.reflect.Field lastMove=OlmMechanicAdapter.class.getDeclaredField("lastMove");lastMove.setAccessible(true);lastMove.set(adapter,c(1,0));view=new OlmSpecials.View();view.player=c(0,0);view.tick=10;check(!adapter.canWeaveHead(view,true),"an issued but unobserved dodge cannot be cancelled by an attack");view.player=c(1,0);check(adapter.canWeaveHead(view,true),"observed arrival opens a same-game-tick attack opportunity");
  Map<String,Object> projectileFields=new HashMap<>();projectileFields.put("getEndCycle",120);Projectile projectile=ChambersTests.fake(Projectile.class,projectileFields);OlmSpecials.Hazard falling=new OlmSpecials.Hazard(c(0,0),OlmSpecials.HazardKind.FALLING,2);java.lang.reflect.Field fallingField=OlmMechanicAdapter.class.getDeclaredField("falling");fallingField.setAccessible(true);@SuppressWarnings("unchecked") Map<Projectile,OlmSpecials.Hazard> pending=(Map<Projectile,OlmSpecials.Hazard>)fallingField.get(adapter);pending.put(projectile,falling);view.hazards.add(falling);check(adapter.canWeaveHead(view,true),"a known later landing permits a brief attack slot after the step");adapter.tickRemainingMs(50);check(!adapter.canWeaveHead(view,true),"do not consume the last movement queueing margin before the next game tick");adapter.tickRemainingMs(300);projectileFields.put("getEndCycle",106);check(!adapter.canWeaveHead(view,true),"imminent landing immediately retains dodge priority");projectileFields.put("getEndCycle",120);view.player=c(0,0);lastMove.set(adapter,c(0,0));check(!adapter.canWeaveHead(view,true),"never pause on the directly targeted crystal tile for DPS");
  OlmAttackTiming clock=new OlmAttackTiming();clock.observed(10,4);check(!clock.ready(11)&&clock.mayRetargetAfterMove(true,true,true,11),"movement arrival permits immediate head reselection during the real weapon cooldown");check(!clock.mayRetargetAfterMove(true,false,true,11)&&!clock.mayRetargetAfterMove(true,true,false,11)&&!clock.mayRetargetAfterMove(false,true,true,11),"no early retarget before arrival, without a new move, or for melee");clock.requested(11);check(!clock.mayRetargetAfterMove(true,true,true,11)&&!clock.ready(12),"pending target request is not repeated and does not shorten the observed weapon cooldown");check(clock.ready(14),"real configured cooldown remains in force after target reselection");
  OlmStrategy strategy=new OlmStrategy();for(int i=0;i<7;i++)strategy.drinkConfirmed();OlmStrategy.View health=OlmStrategyTests.ready();health.entered=health.headAlive=true;health.phase=OlmStrategy.Phase.HEAD;health.hp=80;check(strategy.choose(health).value.equals("aid"),"eighty absolute HP triggers healing before head DPS");health.hp=81;check(strategy.choose(health).value.equals("head"),"healthy player can attack without unnecessary sips");health.hp=75;health.potionPending=true;check(strategy.choose(health).value.equals("head"),"potion cooldown still permits compatible attacks");health.potionPending=false;health.prayerRequired=true;check(strategy.choose(health).kind==OlmStrategy.Kind.WAIT,"protection priority remains ahead of healing");
  health.prayerRequired=false;health.hp=18;health.unavailableSupplies.add("aid");check(strategy.choose(health).value.equals("head"),"unavailable aids cannot starve head attacks at low HP");health.overloadExpired=true;health.unavailableSupplies.add("overload");health.enhanceExpired=true;health.unavailableSupplies.add("enhance");health.prayerPoints=0;health.unavailableSupplies.add("revitalisation");check(strategy.choose(health).value.equals("head"),"missing maintenance supplies do not trap in-combat decisions");health.unavailableSupplies.clear();health.prayerPoints=99;check(strategy.choose(health).value.equals("aid"),"a newly available aid immediately restores healing priority");health.prayerRequired=true;check(strategy.choose(health).kind==OlmStrategy.Kind.WAIT,"missing supplies do not bypass protection priority");  OlmMoveRetry retry=new OlmMoveRetry();retry.requested(c(0,0),c(1,0),10);check(retry.observe(c(0,0),11).isEmpty(),"allow a movement update before excluding an ignored destination");check(retry.observe(c(0,0),12).contains(c(1,0)),"no observed movement for two ticks briefly excludes that destination");check(retry.observe(c(0,0),18).isEmpty(),"temporary exclusion expires rather than inventing permanent collision");retry.requested(c(0,0),c(3,0),20);check(retry.observe(c(1,0),21).isEmpty()&&retry.observe(c(2,0),22).isEmpty()&&retry.observe(c(3,0),23).isEmpty(),"progressing or completed movement is never excluded");retry.reset();check(retry.observe(c(0,0),30).isEmpty(),"new encounters clear retry history");  check(OlmWeaponCadence.speed(OlmWeaponCadence.defaults(),"Holy cards")==2&&OlmWeaponCadence.speed(OlmWeaponCadence.defaults(),"Eye of Ayak")==2,"video timings are two ticks for both named weapons");check(OlmWeaponCadence.speed(OlmWeaponCadence.defaults(),"Other staff")==null,"unrelated weapons retain their own clocks");check(OlmWeaponCadence.attributable(128,128,128,128,1,true,true,false),"fresh unambiguous local projectile confirms a shot");check(!OlmWeaponCadence.attributable(128,128,256,128,1,true,true,false)&&!OlmWeaponCadence.attributable(128,128,128,128,20,true,true,false)&&!OlmWeaponCadence.attributable(128,128,128,128,1,true,true,true)&&!OlmWeaponCadence.attributable(128,128,128,128,1,true,false,false),"wrong origin, stale shot, stacked players or other target cannot confirm attacks");System.out.println("Olm head DPS checks passed: pool shots, observed-step weaving, imminent-impact preemption, clear-pool deadline selection and 80-HP healing. Synthetic only.");
 }
}





